mapper.select:
select t.*, (select count(*) from wm_stock_taking_line l where l.taking_id = t.taking_id and l.del_flag = '0') as line_count, (select count(*) from wm_stock_taking_line l where l.taking_id = t.taking_id and l.del_flag = '0' and l.taking_status = 'CONFIRMED') as counted_count, (select count(*) from wm_stock_taking_line l where l.taking_id = t.taking_id and l.del_flag = '0' and l.diff_quantity is not null and l.diff_quantity != 0) as diff_count, (select ifnull(sum(l.diff_quantity), 0) from wm_stock_taking_line l where l.taking_id = t.taking_id and l.del_flag = '0' and l.diff_quantity > 0) as profit_quantity, (select ifnull(sum(l.diff_quantity), 0) from wm_stock_taking_line l where l.taking_id = t.taking_id and l.del_flag = '0' and l.diff_quantity < 0) as loss_quantity from ( select from wm_stock_taking
del_flag = '0'
and taking_code like concat('%', #{takingCode}, '%')
and taking_name like concat('%', #{takingName}, '%')
and plan_id = #{planId} and status = #{status}
and taking_date >= #{takingDateStart}
and taking_date <= #{takingDateEnd}
order by taking_id desc ) t
